arguments.command:
set -eu
fasttext dump /app/yelp_widehash.bin dict | awk '
NR==1 {declared=$1; next}
$3=="word" {
  n++; c=$2+0;
  if(c>=2)n2++; if(c>=3)n3++; if(c>=4)n4++; if(c>=5)n5++; if(c>=10)n10++;
  if(c==1)once++; if(c==2)twice++;
  chars+=length($1)+1;
}
END {
  printf "declared=%d observed_words=%d chars_plus_nul=%d\n", declared,n,chars;
  printf "count_eq_1=%d count_eq_2=%d\n",once,twice;
  printf "minCount1=%d minCount2=%d minCount3=%d minCount4=%d minCount5=%d minCount10=%d\n",n,n2,n3,n4,n5,n10;
}'
printf '\nCURRENT_FILES\n'
stat -c '%n %s' /app/yelp_widehash.bin /app/yelp_dsub1.ftz /app/yelp_dsub1_nonorm.ftz /app/model.bin 2>/dev/null || true
printf '\nCURRENT_FINAL_TEST\n'
fasttext test /app/model.bin /app/valid.fasttext.txt 1 2>/dev/null || true
